// 수동으로 검토한 문항은 위의 문항별 해설을 그대로 사용한다. 아직 별도 항목이
// 없는 문항도 원문 선택지·지문·문항별 풀이 기준을 함께 넣어 생성 단계에서
// 공통 문구가 남지 않게 한다.
function quoted(value = '') { return value.replace(/\s+/g, ' ').trim() }
function core(value = '') { return quoted(value).slice(0, 110) }
function sentence(value = '') { return quoted(value).replace(/\s*([.。]).*$/, '$1') }
function stemFocus(stem = '') {
  const normalized = quoted(stem).replace(/^다음(?:은)?\s*(?:중|자료에서|빈칸에서)?\s*/, '')
  return normalized.length > 150 ? `${normalized.slice(0, 150)}…` : normalized
}

// 정답 해설과 풀이방향은 같은 문항의 정답 선택지·원문 조건을 바탕으로 함께 만든다.
// 공통 템플릿을 피하고, 생성기에서도 해당 문항의 실제 표현과 검산 기준이 보이게 한다.
export function expertLearningDataFor({ id, stem, options, answer, choiceAnalysis, calculation, topic }) {
  const selected = choiceAnalysis.find((choice) => choice.choiceNo === answer)
  const answerLabel = ['①', '②', '③', '④'][answer - 1]
  const answerText = core(options[answer - 1])
  const reason = selected?.reason || ''
  const focus = stemFocus(stem)
  const numbers = (quoted(stem).match(/\d[\d,.]*(?:%|원|년|개월|개|주|시간|일)?/g) || []).slice(0, 5).join('·')
  const reasoningPoint = sentence(reason)
  const calculationStep = calculation
    ? `계산식 “${calculation.formula}”에 ${numbers || '지문의 수치'}를 순서대로 대입해 ${calculation.substitutions.join(' → ')}를 확인합니다.`
    : `선택지 ${answerLabel}의 “${answerText}”에 적용할 기준은 다음과 같습니다. ${reasoningPoint}`
  return {
    explanation: `AI 학습용 해설 — 정답 선택지 ${answerLabel}의 실제 표현은 “${answerText}”입니다. ${reason}`,
    solutionSteps: [
      `문제의 핵심 조건 “${focus}”에서 정답 선택지 ${answerLabel}의 실제 표현 “${answerText}”를 확인합니다.`,
      calculationStep,
      `위 기준을 적용하면 ${answerLabel} ${answer}번이 확정됩니다. ${reasoningPoint}`,
    ],
    direction: {
      concept: `${topic}: ${reasoningPoint}`,
      strategy: calculation
        ? `${numbers || '지문의 수치'}를 빠짐없이 분리한 뒤, ${calculation.substitutions.join(' → ')}를 계산하고 ${answerLabel}의 ${calculation.result}과 대조합니다.`
        : `문제의 핵심 조건 “${focus}”를 먼저 읽고 ${answerLabel}의 “${answerText}”에 적용합니다. ${reasoningPoint}`,
    },
    commonMistake: calculation
      ? `${answerLabel}의 ${calculation?.result || answerText}을 맞히려면 ${numbers || '지문의 수치'} 중 단위·기간·포함 여부를 바꾸지 않아야 합니다.`
      : `문제의 “${focus}” 조건을 빼고 “${answerText}”만 외우면 비슷한 개념·예외와 혼동하기 쉽습니다. 조건과 표현을 함께 확인합니다.`,
  }
}

