export function detailedChoiceAnalysisFor({ id, options, answer, stem, concept, direction, calculation }) {
  const asksIncorrect = /옳지 않은|아닌 것|해당하지 않는/.test(stem)
  const answerText = core(options[answer - 1])
  const sourcePoint = core(stem)
  const rule = direction?.concept || `${concept}의 적용 요건`
  const calculationRule = calculation?.formula ? `계산 기준은 “${calculation.formula}”이며, ${calculation.result}까지 산출해 선택지와 대조합니다.` : rule
  const saved = detailedChoiceAnalyses[id]
  const analyses = saved || options.map((option, index) => {
    const choiceNo = index + 1
    const optionText = core(option)
    if (choiceNo === answer) {
      return {
        choiceNo,
        verdict: asksIncorrect ? '틀림(정답)' : '정답',
        reason: asksIncorrect
          ? `선택지 ${['①', '②', '③', '④'][index]}의 실제 표현은 “${optionText}”입니다. 이 문항은 “${sourcePoint}”를 묻고, 판단 기준은 ${calculationRule}입니다. 해당 표현이 이 기준의 요건·수치·기간·주체를 잘못 적용했으므로 ‘옳지 않은 것’의 정답입니다.`
          : `선택지 ${['①', '②', '③', '④'][index]}의 실제 표현은 “${optionText}”입니다. 지문 “${sourcePoint}”의 조건을 ${calculationRule}에 순서대로 적용하면 이 표현이 요구한 결론과 일치합니다. 따라서 이 보기가 정답입니다.`,
      }
    }
    return {
      choiceNo,
      verdict: asksIncorrect ? '맞음' : '오답',
      reason: `선택지 ${['①', '②', '③', '④'][index]}의 실제 표현은 “${optionText}”입니다. 지문은 “${sourcePoint}”의 조건을 제시하므로, ${calculationRule}에 비추어 ${['①', '②', '③', '④'][answer - 1]} “${answerText}”와 구별해야 합니다. 이 선택지는 그 조건·예외·계산 결과를 정답처럼 결론내릴 수 없으므로 ${asksIncorrect ? '맞는 설명' : '오답'}입니다.`,
    }
  })
  return analyses.map((choice) => choice.reason.length >= 90 ? choice : {
    ...choice,
    reason: `${choice.reason} 이 보기의 실제 표현 “${core(options[choice.choiceNo - 1])}”을 지문 “${sourcePoint}”의 조건 및 ${calculationRule}와 함께 확인하면, 정답 보기와 혼동하지 않을 수 있습니다.`,
  })
}

